-- Golden fixture: one session from a database written before opencode 1.18.5
-- Captured from a real OpenCode database and redacted: prose, titles,
-- tool inputs and outputs, paths and diffs are neutral text. Ids, keys, types,
-- timestamps, token counts, statuses and structure are the capture's own.

CREATE TABLE session (id TEXT, project_id TEXT, parent_id TEXT, slug TEXT, directory TEXT, title TEXT, version TEXT, time_created INTEGER, time_updated INTEGER);
CREATE TABLE message (id TEXT, session_id TEXT, time_created INTEGER, time_updated INTEGER, data TEXT);
CREATE TABLE part (id TEXT, message_id TEXT, session_id TEXT, time_created INTEGER, time_updated INTEGER, data TEXT);


